// Native workflow draft: copy into the owned fixture only after Payload and
// Envelope fields have been generated through the actual desktop actions.
package fixture

import (
	"encoding/json"
	"io"
	"reflect"
	"strings"
	"testing"
)

// Compile-time checks reject silently generated float64/int64 fields under the
// explicit number policy. Both names also prove Go initialism suggestions.
var _ json.Number = (Payload{}).ID
var _ json.Number = (Envelope{}).Count
var _ string = (Envelope{}).TraceID

const nativeTypeSample = "{\"id\":9007199254740993,\"label\":\"中文😀\",\"items\":[{\"active\":true},{\"active\":false}],\"notes\":null}"
const nativeFieldsSample = "{\"trace_id\":\"中文😀\",\"count\":3,\"extra\":{\"enabled\":true}}"

func decodeNativeJSON(t *testing.T, text string) any {
	t.Helper()
	decoder := json.NewDecoder(strings.NewReader(text))
	decoder.UseNumber()
	var value any
	if err := decoder.Decode(&value); err != nil {
		t.Fatal(err)
	}
	var extra any
	if err := decoder.Decode(&extra); err != io.EOF {
		t.Fatalf("trailing JSON: %v", err)
	}
	return value
}

func assertNativeJSONRoundTrip(t *testing.T, sample string, value any) {
	t.Helper()
	encoded, err := json.Marshal(value)
	if err != nil {
		t.Fatal(err)
	}
	expected, actual := decodeNativeJSON(t, sample), decodeNativeJSON(t, string(encoded))
	if !reflect.DeepEqual(expected, actual) {
		t.Fatalf("JSON value or numeric lexeme changed:\nwant %s\ngot  %s", sample, encoded)
	}
}

func TestNativeGeneratedPayloadRoundTripPreservesExactSamples(t *testing.T) {
	var payload Payload
	if err := json.Unmarshal([]byte(nativeTypeSample), &payload); err != nil {
		t.Fatal(err)
	}
	if payload.ID != json.Number("9007199254740993") {
		t.Fatalf("large ID lost precision: %q", payload.ID)
	}
	if payload.Label != "中文😀" {
		t.Fatalf("Unicode label changed: %q", payload.Label)
	}
	if len(payload.Items) != 2 || !payload.Items[0].Active || payload.Items[1].Active {
		t.Fatalf("nested items changed: %+v", payload.Items)
	}
	if !json.Valid(payload.Notes) || string(payload.Notes) != "null" {
		t.Fatalf("explicit null changed: %s", payload.Notes)
	}
	assertNativeJSONRoundTrip(t, nativeTypeSample, payload)
}

func TestNativeGeneratedEnvelopeFieldsPreserveExistingTagAndRoundTrip(t *testing.T) {
	existing, ok := reflect.TypeOf(Envelope{}).FieldByName("Existing")
	if !ok || existing.Type != reflect.TypeOf("") || existing.Tag.Get("json") != "existing,omitempty" {
		t.Fatalf("original Existing field/type/tag changed: %+v", existing)
	}
	var envelope Envelope
	if err := json.Unmarshal([]byte(nativeFieldsSample), &envelope); err != nil {
		t.Fatal(err)
	}
	if envelope.Existing != "" || envelope.TraceID != "中文😀" || envelope.Count != json.Number("3") || !envelope.Extra.Enabled {
		t.Fatalf("generated fields decoded incorrectly: %+v", envelope)
	}
	assertNativeJSONRoundTrip(t, nativeFieldsSample, envelope)
	// Also prove that the original, unrelated field retains its JSON tag and is
	// still serialized once nonempty, rather than being replaced or ignored.
	envelope.Existing = "kept 原字段😀"
	encoded, err := json.Marshal(envelope)
	if err != nil {
		t.Fatal(err)
	}
	object, ok := decodeNativeJSON(t, string(encoded)).(map[string]any)
	if !ok || object["existing"] != envelope.Existing {
		t.Fatalf("existing tag stopped working: %s", encoded)
	}
}
